    leadId: ALICE,
    color: "#6366f1",
    startsAt: null,
    targetDate: null,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeIssue(overrides: Partial<Issue> = {}): Issue {
  return {
    id: nextId() as IssueId,
    orgId: ORG_A,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    number: 1,
