/**
 * Calendar arithmetic for recurring issues.
 *
 * Everything here works on `YYYY-MM-DD` calendar days, never on instants: a
 * rule's day D is "in" a time zone, and the only place an instant enters is
 * `localDateIn()`, which asks the runtime's tz database what day it currently
 * is there. Keeping the rest on plain dates is what makes daylight-saving
 * transitions a non-issue — a 23- or 25-hour day is still one calendar day.
 *
 * Pure and dependency-free, so the create schema can validate with it too.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** `+05:00` / `-0330` style offsets: V8 accepts them, but they are not IANA zones. */
const OFFSET_ZONE = /^[+-]\d{2}(?::?\d{2})?$/;

const dayFormats = new Map<string, Intl.DateTimeFormat>();

/** A `Date` at 00:00 UTC on `date`, or `null` unless it is a real calendar day. */
function parseCalendarDate(date: string): Date | null {
  const match = CALENDAR_DATE.exec(date);
  if (match === null) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  // `setUTCFullYear` rather than `Date.UTC`, which reads years 0–99 as 19xx.
  const parsed = new Date(0);
  parsed.setUTCFullYear(year, month - 1, day);

  const roundTrips =
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day;

  return roundTrips ? parsed : null;
}

function formatCalendarDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** True for a real `YYYY-MM-DD` day — `2026-02-30` is not one. */
export function isCalendarDate(value: string): boolean {
  return parseCalendarDate(value) !== null;
}

/** True when the runtime's tz database knows `value` as an IANA zone name. */
export function isKnownTimeZone(value: string): boolean {
  if (value.length === 0 || OFFSET_ZONE.test(value)) return false;

  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

/**
 * The calendar day it is in `timeZone` at the instant `at`. Occurrence day D
 * has started exactly when this is >= D: the local clock has reached 00:00 on
 * D, whether or not that wall-clock time was skipped by a DST jump.
 */
export function localDateIn(timeZone: string, at: Date): string {
  let format = dayFormats.get(timeZone);
  if (format === undefined) {
    format = new Intl.DateTimeFormat("en-US", {
      timeZone,
      calendar: "gregory",
      numberingSystem: "latn",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    dayFormats.set(timeZone, format);
  }

  const parts = format.formatToParts(at);
  const read = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((part) => part.type === type)?.value ?? "";

  return `${read("year").padStart(4, "0")}-${read("month")}-${read("day")}`;
}

/** ISO weekday of a calendar day: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(date: string): number {
  const parsed = parseCalendarDate(date);
  if (parsed === null) throw new RangeError(`Not a calendar date: "${date}"`);
  return parsed.getUTCDay() === 0 ? 7 : parsed.getUTCDay();
}

/** `date` shifted by a whole number of calendar days (negative goes back). */
export function addCalendarDays(date: string, days: number): string {
  const parsed = parseCalendarDate(date);
  if (parsed === null) throw new RangeError(`Not a calendar date: "${date}"`);
  parsed.setUTCDate(parsed.getUTCDate() + days);
  return formatCalendarDate(parsed);
}

export interface OccurrenceRule {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * The latest occurrence of `rule` that has started by `now`, or `null` when
 * none has (the rule starts in the future, or no matching weekday has come
 * round yet). A daily rule occurs every day from `startsOn`; a weekly rule on
 * each day from `startsOn` whose ISO weekday is `rule.weekday`.
 */
export function latestOccurrenceOn(
  rule: OccurrenceRule,
  now: Date,
): string | null {
  const today = localDateIn(rule.timezone, now);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;
  if (rule.weekday === null) return null;

  const daysSince = (isoWeekdayOf(today) - rule.weekday + 7) % 7;
  const latest = addCalendarDays(today, -daysSince);

  return latest >= rule.startsOn ? latest : null;
}

