/**
 * Recurring-issue rules. Every tenant read is filtered by `orgId`; the one
 * cross-tenant read is the job's work list.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";

/** What a caller supplies; the repository owns id, bookkeeping and progress. */
export type NewRecurringIssue = Omit<
  RecurringIssue,
  "id" | "lastOccurrenceOn" | "paused" | "createdAt" | "updatedAt"
>;

export async function findRecurringIssue(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/**
 * Creation order is insertion order. `rowid` rather than `created_at` (two
 * rules made in one millisecond tie) or `id` (ULIDs minted in one millisecond
 * are random past the timestamp).
 */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(sql`rowid`))
    .all()
    .map(toRecurringIssue);
}

/** Every rule counts against the plan quota, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/**
 * Inserts a fresh, unpaused rule unless the organization already holds
 * `maxRules`; resolves `null` in that case. The count and the insert share one
 * synchronous transaction, so concurrent creates cannot both slip in under the
 * cap. `maxRules` may be `Infinity`.
 */
export async function insertRecurringIssue(
  input: NewRecurringIssue,
  maxRules: number,
): Promise<RecurringIssue | null> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb().transaction((tx) => {
    const existing = tx
      .select({ value: count() })
      .from(recurringIssues)
      .where(orgPredicate(recurringIssues.orgId, input.orgId))
      .get();

    if ((existing?.value ?? 0) >= maxRules) return null;

    return tx
      .insert(recurringIssues)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        title: input.title,
        priority: input.priority,
        assigneeId: input.assigneeId,
        cadence: input.cadence,
        weekday: input.weekday,
        timezone: input.timezone,
        startsOn: input.startsOn,
        lastOccurrenceOn: null,
        paused: false,
        createdBy: input.createdBy,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();
  });

  return row ? toRecurringIssue(row) : null;
}

export async function updatePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

/** Records the occurrence the job just filed. */
export async function updateLastOccurrence(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

/**
 * The job's work list: every unpaused rule of every organization, oldest
 * first. Cross-tenant on purpose — the sweep runs in the background, not for
 * one actor — so callers must scope each rule to its own `orgId` afterwards.
 */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(sql`rowid`))
    .all()
    .map(toRecurringIssue);
}

