/**
 * Recurring-issue rules: who may define them, how many a plan allows and how they are paused. Filing the issues is the job's business.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, checkLimit
 */
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { checkLimit } from "./billing-service";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { LimitCheck } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

/**
 * Creating a rule needs the same permission as filing an issue by hand in the
 * rule's project, because that is what the job later does on the actor's
 * behalf. Every rule counts against the plan's `recurringIssues` quota,
 * paused ones included.
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);

  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error(
        `User ${parsed.assigneeId} is not an active member of this organization`,
      );
    }
  }

  const quota = await checkLimit(parsed.orgId, "recurringIssues");
  if (quota.exceeded) throw quotaError(quota);

  // The repository re-checks the cap atomically with the insert, so two
  // creates racing past the read above still cannot exceed it.
  const created = await recurringIssueRepo.insertRecurringIssue(
    {
      orgId: parsed.orgId,
      projectId: parsed.projectId,
      title: parsed.title,
      priority: parsed.priority,
      assigneeId: parsed.assigneeId,
      cadence: parsed.cadence,
      weekday: parsed.weekday,
      timezone: parsed.timezone,
      startsOn: parsed.startsOn,
      createdBy: actor.userId,
    },
    quota.limit,
  );
  if (created === null) throw quotaError(quota);

  return created;
}

/** Pausing (and resuming) is gated like creating: the rule files issues for its project. */
export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringIssueRepo.findRecurringIssue(
      input.orgId,
      input.recurringIssueId,
    ),
    "Recurring issue",
    input.recurringIssueId,
  );

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringIssueRepo.updatePaused(
    input.orgId,
    rule.id,
    input.paused,
  );
}

/** Rules in the order they were created. */
export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}

function quotaError(quota: LimitCheck): Error {
  return new Error(
    `Plan ${quota.plan} allows ${quota.limit} recurring issues; ${quota.used} are in use`,
  );
}

