/**
 * Files the issue each due recurring-issue rule calls for, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): createIssue, latestOccurrenceOn
 */
import { createLogger } from "@/lib/logger";
import { PermissionDeniedError } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { latestOccurrenceOn } from "@/lib/recurrence";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { CreateIssueInput } from "@/schemas/issue";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

type Outcome = "created" | "skipped" | "paused" | "refused";

/**
 * Runs are chained: two overlapping sweeps (the scheduler's tick and an admin
 * "run now") would otherwise both see the same due occurrence and file it
 * twice.
 */
let previousRun: Promise<unknown> = Promise.resolve();

/**
 * Looks at every unpaused rule and files, at most once per rule, the latest
 * occurrence that has started by `now`. Missed occurrences are never
 * back-filled, and a rule whose latest occurrence is already recorded is left
 * alone, so running again for the same `now` files nothing new.
 *
 * The issue goes through `createIssue` as the rule's creator, so it meets the
 * same checks and emits the same events as one filed by hand. When that is
 * refused for a reason a later run could get past (say the project is at its
 * issue quota) the rule is left exactly as it was; when the creator can no
 * longer file issues at all, the rule is paused instead.
 */
export function runRecurringIssueJob(now: Date): Promise<JobResult> {
  const run = previousRun.then(
    () => sweep(now),
    () => sweep(now),
  );
  previousRun = run;
  return run;
}

async function sweep(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const outcome = await processRule(rule, now);

        if (outcome === "created") result.processed += 1;
        if (outcome === "refused") result.failed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue failed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processRule(rule: RecurringIssue, now: Date): Promise<Outcome> {
  const occurrence = latestOccurrenceOn(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  // An archived project is skipped without a trace: once it is restored the
  // next run files whatever occurrence is then the latest.
  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return "skipped";

  const actor = await actorFor(rule, rule.createdBy);
  if (actor === null) return pause(rule, "creator is no longer an active member");

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId: await assigneeFor(rule),
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    } satisfies CreateIssueInput);
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      return pause(rule, "creator's role no longer allows creating issues");
    }

    logger.warn("recurring issue not created; will retry next run", {
      recurringIssueId: rule.id,
      orgId: rule.orgId,
      occurrence,
      reason: error instanceof Error ? error.message : String(error),
    });
    return "refused";
  }

  await recurringIssueRepo.updateLastOccurrence(
    rule.orgId,
    rule.id,
    occurrence,
  );
  return "created";
}

/** The creator as they are today: an active member, with their current role. */
async function actorFor(
  rule: RecurringIssue,
  userId: UserId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(rule.orgId, userId);
  if (member === null || member.status !== "active") return null;

  return { userId, orgId: rule.orgId, role: member.role };
}

/** The rule's assignee while they are still an active member, else nobody. */
async function assigneeFor(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;

  const member = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return member !== null && member.status === "active" ? rule.assigneeId : null;
}

async function pause(rule: RecurringIssue, reason: string): Promise<Outcome> {
  await recurringIssueRepo.updatePaused(rule.orgId, rule.id, true);
  logger.warn("recurring issue paused", {
    recurringIssueId: rule.id,
    orgId: rule.orgId,
    reason,
  });
  return "paused";
}

