cat > tests/lib/recurrence.test.ts <<'EOF'
/** Calendar-day arithmetic behind recurring issues: validation, local dates and the latest occurrence. */
import { describe, expect, it } from "vitest";
import {
  addCalendarDays,
  isCalendarDate,
  isKnownTimeZone,
  isoWeekdayOf,
  latestOccurrenceOn,
  localDateIn,
} from "@/lib/recurrence";
import type { OccurrenceRule } from "@/lib/recurrence";

const daily = (timezone: string, startsOn: string): OccurrenceRule => ({
  cadence: "daily",
  weekday: null,
  timezone,
  startsOn,
});

const weekly = (
  weekday: number,
  timezone: string,
  startsOn: string,
): OccurrenceRule => ({ cadence: "weekly", weekday, timezone, startsOn });

describe("lib/recurrence", () => {
  it("accepts only real calendar days", () => {
    expect(isCalendarDate("2026-02-28")).toBe(true);
    expect(isCalendarDate("2028-02-29")).toBe(true);
    expect(isCalendarDate("2026-02-29")).toBe(false);
    expect(isCalendarDate("2026-02-30")).toBe(false);
    expect(isCalendarDate("2026-13-01")).toBe(false);
    expect(isCalendarDate("2026-00-10")).toBe(false);
    expect(isCalendarDate("2026-4-05")).toBe(false);
    expect(isCalendarDate("2026-04-05T00:00:00Z")).toBe(false);
    expect(isCalendarDate("")).toBe(false);
  });

  it("accepts only IANA zone names the runtime knows", () => {
    expect(isKnownTimeZone("UTC")).toBe(true);
    expect(isKnownTimeZone("Europe/Berlin")).toBe(true);
    expect(isKnownTimeZone("America/Argentina/Buenos_Aires")).toBe(true);
    expect(isKnownTimeZone("Mars/Olympus_Mons")).toBe(false);
    expect(isKnownTimeZone("")).toBe(false);
    expect(isKnownTimeZone("+05:00")).toBe(false);
    expect(isKnownTimeZone("CET-1")).toBe(false);
  });

  it("numbers weekdays 1 = Monday … 7 = Sunday and steps whole days", () => {
    expect(isoWeekdayOf("2026-03-02")).toBe(1);
    expect(isoWeekdayOf("2026-03-08")).toBe(7);
    expect(addCalendarDays("2026-03-01", -1)).toBe("2026-02-28");
    expect(addCalendarDays("2028-02-28", 2)).toBe("2028-03-01");
    expect(addCalendarDays("2025-12-31", 1)).toBe("2026-01-01");
  });

  it("reads the local day in the rule's zone", () => {
    const instant = new Date("2026-03-05T23:30:00.000Z");
    expect(localDateIn("UTC", instant)).toBe("2026-03-05");
    expect(localDateIn("Asia/Tokyo", instant)).toBe("2026-03-06");
    expect(localDateIn("America/Los_Angeles", instant)).toBe("2026-03-05");
  });

  it("starts a day when the local clock passes midnight, DST included", () => {
    // Berlin springs forward on 2026-03-29 (01:00 UTC): the day still starts
    // at local midnight, i.e. 23:00 UTC the evening before.
    const rule = daily("Europe/Berlin", "2026-01-01");
    expect(latestOccurrenceOn(rule, new Date("2026-03-28T22:59:59.000Z"))).toBe("2026-03-28");
    expect(latestOccurrenceOn(rule, new Date("2026-03-28T23:00:00.000Z"))).toBe("2026-03-29");

    // ...and on 2026-10-25 the offset shrinks, so midnight is 22:00 UTC.
    expect(latestOccurrenceOn(rule, new Date("2026-10-24T21:59:59.000Z"))).toBe("2026-10-24");
    expect(latestOccurrenceOn(rule, new Date("2026-10-24T22:00:00.000Z"))).toBe("2026-10-25");
  });

  it("has no occurrence before startsOn", () => {
    const rule = daily("UTC", "2026-03-10");
    expect(latestOccurrenceOn(rule, new Date("2026-03-09T23:59:59.000Z"))).toBeNull();
    expect(latestOccurrenceOn(rule, new Date("2026-03-10T00:00:00.000Z"))).toBe("2026-03-10");
  });

  it("finds the latest matching weekday on or after startsOn", () => {
    // 2026-03-04 is a Wednesday.
    const now = new Date("2026-03-04T12:00:00.000Z");
    expect(latestOccurrenceOn(weekly(1, "UTC", "2026-01-01"), now)).toBe("2026-03-02");
    expect(latestOccurrenceOn(weekly(3, "UTC", "2026-01-01"), now)).toBe("2026-03-04");
    expect(latestOccurrenceOn(weekly(7, "UTC", "2026-01-01"), now)).toBe("2026-03-01");
    expect(latestOccurrenceOn(weekly(1, "UTC", "2026-03-03"), now)).toBeNull();
    expect(latestOccurrenceOn(weekly(1, "UTC", "2026-03-02"), now)).toBe("2026-03-02");
  });
});
EOF
cat > tests/schemas/recurring-issue.schema.test.ts <<'EOF'
import { describe, expect, it } from "vitest";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";

const ORG = "01HZZZAAAAAAAAAAAAAAAAAAAA";
const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";
const USER = "01HZZZAAAAAAAAAAAAAAAAAAA1";

function valid(overrides: Record<string, unknown> = {}) {
  return {
    orgId: ORG,
    projectId: PROJECT,
    title: "Daily triage",
    cadence: "daily",
    timezone: "Europe/Berlin",
    startsOn: "2026-03-02",
    ...overrides,
  };
}

describe("schemas/recurring-issue", () => {
  it("applies the defaults", () => {
    const parsed = createRecurringIssueSchema.parse(valid());
    expect(parsed).toMatchObject({
      priority: "none",
      assigneeId: null,
      weekday: null,
    });
  });

  it("requires a weekday for weekly rules and forbids one for daily rules", () => {
    expect(
      createRecurringIssueSchema.safeParse(valid({ cadence: "weekly" })).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(valid({ cadence: "weekly", weekday: 1 })).success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse(valid({ cadence: "daily", weekday: 3 })).success,
    ).toBe(false);
  });

  it("keeps the weekday within 1–7", () => {
    for (const weekday of [0, 8, 1.5, -1]) {
      expect(
        createRecurringIssueSchema.safeParse(valid({ cadence: "weekly", weekday })).success,
      ).toBe(false);
    }
    expect(
      createRecurringIssueSchema.safeParse(valid({ cadence: "weekly", weekday: 7 })).success,
    ).toBe(true);
  });

  it("bounds the title to 3–180 characters", () => {
    expect(createRecurringIssueSchema.safeParse(valid({ title: "ab" })).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse(valid({ title: "a".repeat(180) })).success).toBe(true);
    expect(createRecurringIssueSchema.safeParse(valid({ title: "a".repeat(181) })).success).toBe(false);
  });

  it("rejects unknown time zones and impossible dates", () => {
    expect(createRecurringIssueSchema.safeParse(valid({ timezone: "Mars/Olympus" })).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse(valid({ startsOn: "2026-02-30" })).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse(valid({ startsOn: "03/02/2026" })).success).toBe(false);
  });

  it("validates ids like the other schemas do", () => {
    expect(createRecurringIssueSchema.safeParse(valid({ orgId: "nope" })).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse(valid({ projectId: "nope" })).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse(valid({ assigneeId: "nope" })).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse(valid({ assigneeId: USER })).success).toBe(true);
  });
});
EOF
