        ruleInput(starter, { title: "Rule 4" }),
      ),
    ).rejects.toThrow();
    expect(await recurringIssueRepo.countRecurringIssues(starter.org.id)).toBe(3);

    const free = await createTenant("recufree", "free");
    await expect(
      recurringService.createRecurringIssue(free.actors.member, ruleInput(free)),
    ).rejects.toThrow();
    expect(await recurringIssueRepo.countRecurringIssues(free.org.id)).toBe(0);
  });

  it("cannot be raced past the cap", async () => {
    const starter = await createTenant("recurace", "starter");
    const results = await Promise.allSettled(
      Array.from({ length: 6 }, (_, n) =>
        recurringService.createRecurringIssue(
          starter.actors.member,
          ruleInput(starter, { title: `Racer ${n}` }),
        ),
      ),
    );

    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(3);
    expect(await recurringIssueRepo.countRecurringIssues(starter.org.id)).toBe(3);
  });

