      ruleInput(tenant, { title: "Pausable" }),
    );
    const input = { orgId: tenant.org.id, recurringIssueId: rule.id };

    await expect(
      recurringService.setRecurringIssuePaused(tenant.actors.viewer, { ...input, paused: true }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const paused = await recurringService.setRecurringIssuePaused(
      tenant.actors.member,
      { ...input, paused: true },
    );
    expect(paused.paused).toBe(true);

    const resumed = await recurringService.setRecurringIssuePaused(
      tenant.actors.member,
      { ...input, paused: false },
    );
    expect(resumed.paused).toBe(false);
  });

  it("scopes pausing to the actor's organization", async () => {
    const other = await createTenant("recupauseother");
    const rule = await recurringService.createRecurringIssue(
      other.actors.member,
      ruleInput(other),
    );

    await expect(
      recurringService.setRecurringIssuePaused(tenant.actors.member, {
        orgId: other.org.id,
        recurringIssueId: rule.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      recurringService.setRecurringIssuePaused(tenant.actors.member, {
        orgId: tenant.org.id,
        recurringIssueId: rule.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lists an organization's rules in creation order", async () => {
    const t = await createTenant("recuList");
    for (const title of ["Third by name", "Alpha", "Middle"]) {
      await recurringService.createRecurringIssue(
        t.actors.member,
        ruleInput(t, { title }),
      );
    }

    const rules = await recurringService.listRecurringIssues(t.actors.viewer, t.org.id);
    expect(rules.map((rule) => rule.title)).toEqual(["Third by name", "Alpha", "Middle"]);

    await expect(
      recurringService.listRecurringIssues(t.actors.viewer, tenant.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});
