  it("pauses and resumes with the create-issue permission", async () => {
    const rule = await recurringService.createRecurringIssue(
      tenant.actors.member,
      ruleInput(tenant, { title: "Pausable" }),
    );
    const input = { orgId: tenant.org.id, recurringIssueId: rule.id };

