 * occurrence only, once, as the rule's creator, without disturbing rules it
 * cannot act on.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { drain, resetQueue, enqueue } from "@/server/jobs/queue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as recurringService from "@/server/services/recurring-issue-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** A Thursday. */
const NOW = new Date("2026-03-05T09:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
});

afterAll(() => {
  cleanup();
});

function ruleInput(
  t: Tenant,
  overrides: Partial<CreateRecurringIssueInput> = {},
): CreateRecurringIssueInput {
  return {
    orgId: t.org.id,
    projectId: t.project.id,
    title: "Daily triage",
    cadence: "daily",
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...overrides,
  };
}

async function issuesOf(t: Tenant) {
  const page = await issueRepo.listIssues({
    orgId: t.org.id,
    limit: 100,
    cursor: null,
    includeArchived: true,
  });
  return [...page.items].sort((a, b) => a.title.localeCompare(b.title));
}

async function makeRule(t: Tenant, overrides: Partial<CreateRecurringIssueInput> = {}) {
  return recurringService.createRecurringIssue(t.actors.member, ruleInput(t, overrides));
}

async function reload(t: Tenant, id: string) {
  const rule = await recurringIssueRepo.findRecurringIssue(t.org.id, id);
  if (rule === null) throw new Error("rule vanished");
  return rule;
}

describe("jobs/recurring-issue-job", () => {
  it("files the latest occurrence as an ordinary backlog issue by the creator", async () => {
    const t = await createTenant("recjobbasic");
    const rule = await makeRule(t, { priority: "high", assigneeId: t.userIds.admin });

    const created: unknown[] = [];
    detachers.push(subscribe("issue.created", (payload) => void created.push(payload)));

    const result = await runRecurringIssueJob(NOW);

    expect(result).toMatchObject({ kind: "recurring-issues", processed: 1, failed: 0 });

    const [issue, ...rest] = await issuesOf(t);
    expect(rest).toHaveLength(0);
    expect(issue).toMatchObject({
      title: "Daily triage (2026-03-05)",
      projectId: t.project.id,
      status: "backlog",
      priority: "high",
      description: null,
      dueAt: null,
      labelIds: [],
      authorId: t.userIds.member,
      assigneeId: t.userIds.admin,
    });
    expect(created).toHaveLength(1);
    expect(created[0]).toMatchObject({ actorId: t.userIds.member, issueId: issue?.id });
    expect((await reload(t, rule.id)).lastOccurrenceOn).toBe("2026-03-05");
  });

  it("does nothing when run again for the same moment", async () => {
    const t = await createTenant("recjobagain");
    await makeRule(t);

    await runRecurringIssueJob(NOW);
    const second = await runRecurringIssueJob(NOW);

    expect(second.processed).toBe(0);
    expect(await issuesOf(t)).toHaveLength(1);
  });

  it("does not run two overlapping sweeps into a duplicate", async () => {
    const t = await createTenant("recjobrace");
    await makeRule(t);

    await Promise.all([runRecurringIssueJob(NOW), runRecurringIssueJob(NOW)]);

    expect(await issuesOf(t)).toHaveLength(1);
  });

  it("never back-fills missed days: one issue, for the latest occurrence", async () => {
    const t = await createTenant("recjobgap");
    const rule = await makeRule(t);

    await runRecurringIssueJob(new Date("2026-03-02T08:00:00.000Z"));
    await runRecurringIssueJob(NOW);

    const titles = (await issuesOf(t)).map((issue) => issue.title);
    expect(titles).toEqual(["Daily triage (2026-03-02)", "Daily triage (2026-03-05)"]);
    expect((await reload(t, rule.id)).lastOccurrenceOn).toBe("2026-03-05");
  });

  it("waits for startsOn and for the weekday to come round", async () => {
    const t = await createTenant("recjobweekly");
    await makeRule(t, { title: "Future", startsOn: "2026-03-06" });
    // 2026-03-05 is a Thursday: Monday rules file Monday the 2nd, and a rule
    // that only starts on Wednesday the 4th has not seen a Monday yet.
    await makeRule(t, { title: "Monday planning", cadence: "weekly", weekday: 1 });
    await makeRule(t, { title: "Late Monday", cadence: "weekly", weekday: 1, startsOn: "2026-03-04" });

    const result = await runRecurringIssueJob(NOW);

    expect(result.processed).toBe(1);
    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Monday planning (2026-03-02)",
    ]);
  });

  it("reads the day in the rule's own time zone", async () => {
    const t = await createTenant("recjobzone");
    await makeRule(t, { title: "Tokyo", timezone: "Asia/Tokyo" });
    await makeRule(t, { title: "Honolulu", timezone: "Pacific/Honolulu" });

    // 23:30 UTC on the 5th is already the 6th in Tokyo, still the 5th in Honolulu.
    await runRecurringIssueJob(new Date("2026-03-05T23:30:00.000Z"));

    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Honolulu (2026-03-05)",
      "Tokyo (2026-03-06)",
    ]);
  });

  it("skips a rule whose project is archived, then catches up once restored", async () => {
    const t = await createTenant("recjobarch");
    const rule = await makeRule(t);

    await projectRepo.archiveProject(t.org.id, t.project.id);
    const skipped = await runRecurringIssueJob(NOW);

    expect(skipped).toMatchObject({ processed: 0, failed: 0 });
    expect(await reload(t, rule.id)).toEqual(rule);

    await projectRepo.restoreProject(t.org.id, t.project.id);
    await runRecurringIssueJob(new Date("2026-03-07T09:00:00.000Z"));

    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Daily triage (2026-03-07)",
    ]);
  });

  it("pauses the rule when its creator is no longer an active member", async () => {
    const t = await createTenant("recjobgone");
    const rule = await makeRule(t);
    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    if (member === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(t.org.id, member.id);

    const result = await runRecurringIssueJob(NOW);

    expect(result.processed).toBe(0);
    expect(await issuesOf(t)).toHaveLength(0);
    expect(await reload(t, rule.id)).toMatchObject({ paused: true, lastOccurrenceOn: null });
  });

  it("pauses the rule when the creator's role no longer allows creating issues", async () => {
    const t = await createTenant("recjobdemote");
    const rule = await makeRule(t);
    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    if (member === null) throw new Error("fixture member missing");
    await memberRepo.updateMemberRole(t.org.id, member.id, "viewer");

    await runRecurringIssueJob(NOW);

    expect(await issuesOf(t)).toHaveLength(0);
    expect(await reload(t, rule.id)).toMatchObject({ paused: true, lastOccurrenceOn: null });

    // A paused rule is no longer looked at.
    await memberRepo.updateMemberRole(t.org.id, member.id, "member");
    await runRecurringIssueJob(NOW);
    expect(await issuesOf(t)).toHaveLength(0);
  });

  it("leaves the assignee off when they are no longer an active member", async () => {
    const t = await createTenant("recjobassignee");
    await makeRule(t, { assigneeId: t.userIds.viewer });
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (viewer === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(t.org.id, viewer.id);

    await runRecurringIssueJob(NOW);

    const [issue] = await issuesOf(t);
    expect(issue?.assigneeId).toBeNull();
  });

  it("leaves the rule untouched when issue creation is refused, and retries later", async () => {
    const t = await createTenant("recjobquota", "free");
    // The free plan holds no rules, so seed the rule through the repository.
    const rule = await recurringIssueRepo.insertRecurringIssue(
      {
        orgId: t.org.id,
        projectId: t.project.id,
        title: "Daily triage",
        priority: "none",
        assigneeId: null,
        cadence: "daily",
        weekday: null,
        timezone: "UTC",
        startsOn: "2026-03-01",
        createdBy: t.userIds.member,
      },
      Number.POSITIVE_INFINITY,
    );
    if (rule === null) throw new Error("seed failed");

    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(t.org.id, t.project.id, { title: `Seed ${number}` }),
        t.userIds.owner,
        number,
      );
    }

    const result = await runRecurringIssueJob(NOW);

    expect(result).toMatchObject({ processed: 0, failed: 1 });
    expect(await reload(t, rule.id)).toEqual(rule);
    expect(await issuesOf(t)).toHaveLength(100);
  });

  it("keeps going when one rule fails", async () => {
    const t = await createTenant("recjobisolate", "growth");
    const full = await createTenant("recjobfull", "free");
    await recurringIssueRepo.insertRecurringIssue(
      {
        orgId: full.org.id,
        projectId: full.project.id,
        title: "Blocked",
        priority: "none",
        assigneeId: null,
        cadence: "daily",
        weekday: null,
        timezone: "UTC",
        startsOn: "2026-03-01",
        createdBy: full.userIds.member,
      },
      Number.POSITIVE_INFINITY,
    );
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(full.org.id, full.project.id, { title: `Seed ${number}` }),
        full.userIds.owner,
        number,
      );
    }
    // A rule that cannot even be evaluated must not take the others down.
    await recurringIssueRepo.insertRecurringIssue(
      {
        orgId: t.org.id,
        projectId: t.project.id,
        title: "Broken zone",
        priority: "none",
        assigneeId: null,
        cadence: "daily",
        weekday: null,
        timezone: "Not/AZone",
        startsOn: "2026-03-01",
        createdBy: t.userIds.member,
      },
      Number.POSITIVE_INFINITY,
    );
    await makeRule(t, { title: "Healthy" });

    const result = await runRecurringIssueJob(NOW);

    expect(result).toMatchObject({ processed: 1, failed: 2 });
    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual(["Healthy (2026-03-05)"]);
  });

  it("handles a rule of an organization the assignee never belonged to", async () => {
    const t = await createTenant("recjobforeign");
    const outsider = await userRepo.insertUser({
      email: "outsider@recjobforeign.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    await recurringIssueRepo.insertRecurringIssue(
      {
        orgId: t.org.id,
        projectId: t.project.id,
        title: "Outsider rule",
        priority: "none",
        assigneeId: outsider.id,
        cadence: "daily",
        weekday: null,
        timezone: "UTC",
        startsOn: "2026-03-01",
        createdBy: t.userIds.member,
      },
      Number.POSITIVE_INFINITY,
    );

    await runRecurringIssueJob(NOW);

    const [issue] = await issuesOf(t);
    expect(issue?.assigneeId).toBeNull();
  });

  it("runs from the queue as the recurring-issues kind", async () => {
    const t = await createTenant("recjobqueue");
    await makeRule(t, { startsOn: "2020-01-01" });

    enqueue({
      id: "recurring-issues:test",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(await issuesOf(t)).toHaveLength(1);
  });
});
